/// `mcp`, its help from `schema`: the toolsets, the API key headers.
pub fn command(app: &App, schema: Option<&Schema>) -> Command {
    let (name, prefix) = (app.name, app.env_prefix);
    let command = Command::new("mcp")
        .about(match cfg!(feature = "mcp-http") {
            true => "Serve the API's operations as the tools of an MCP server, on stdio or over HTTP",
            false => "Serve the API's operations as the tools of an MCP server, on stdin and stdout",
        })
        .long_about(format!(
            "Serve the API's operations as the tools of a Model Context Protocol server, on stdin \
             and stdout: a tool per operation, named after its command (`things create` is \
             things_create), whose input is its parameters and `body`, checked like the \
             command's. Results are the API's JSON, as text and structuredContent, which `jq` \
             filters. Lists return {{items, has_more, next}}, at most `max_items` items \
             ({DEFAULT_MAX_ITEMS} by default); files, base64 resources; errors, the error JSON of \
             the command with isError. Event streams are left out.\n\n\
             Tool schemas suit the client its clientInfo names, or --client: $ref for claude and \
             vscode, every schema inlined for the others.\n\n\
             Credentials are those of the command line: --profile, --api-key, \
             {prefix}_API_KEY, the default profile. In an MCP client's configuration:\n\n  \
             {{\"command\": \"{name}\", \"args\": [\"mcp\"], \"env\": {{\"{prefix}_API_KEY\": \"...\"}}}}\n\n\
             With Claude Code: claude mcp add {name} -e {prefix}_API_KEY=... -- {name} mcp{}",
            http_help(schema)
        ))
        .arg(
            Arg::new("toolsets")
                .long("toolsets")
                .value_name("NAME,...")
                .value_delimiter(',')
                .action(ArgAction::Append)
                .help(toolsets_help(schema)),
        )
        .arg(
            Arg::new("tools")
                .long("tools")
                .value_name("GLOB,...")
                .value_delimiter(',')
                .action(ArgAction::Append)
                .help("Serve only the tools whose name matches one of these globs, whatever the toolsets: customers_*,plans_list"),
        )
        .arg(
            Arg::new("exclude-tools")
                .long("exclude-tools")
                .value_name("GLOB,...")
                .value_delimiter(',')
                .action(ArgAction::Append)
                .help("Leave out the tools whose name matches one of these globs, whatever --tools says"),
        )
        .arg(
            Arg::new("read-only")
                .long("read-only")
                .action(ArgAction::SetTrue)
                .help("Serve the tools of GET operations only, whatever --tools says"),
        )
        .arg(
            Arg::new("client")
                .long("client")
                .value_name("CLIENT")
                .value_parser(Dialect::NAMES)
                .help("Serve the JSON Schema this client takes, whatever its clientInfo says"),
        )
        .arg(
            Arg::new("max-chars")
                .long("max-chars")
                .value_name("N")
                .value_parser(value_parser!(usize))
                .help(format!(
                    "Cut results longer than this many characters, 0 for no limit [default: {DEFAULT_MAX_CHARS}]"
                )),
        )
        .arg(
            Arg::new("list")
                .long("list")
                .action(ArgAction::SetTrue)
                .help("Print the tools as JSON, as the client would get them, and exit"),
        );
    #[cfg(feature = "mcp-http")]
    let command = command.args(super::mcp_http::args(app));
    command
}

/// The paragraph of `mcp --help` on `--port`, with the `mcp-http` feature.
fn http_help(schema: Option<&Schema>) -> String {
    if !cfg!(feature = "mcp-http") {
        return String::new();
    }
    let headers = schema.map(Schema::api_key_headers);
    let header = (headers.unwrap_or_default().first())
        .map(|header| format!(" or {header}: <KEY>"))
        .unwrap_or_default();
    format!(
        "\n\nWith --port, over Streamable HTTP at http://127.0.0.1:<PORT>/mcp, stateless: each POST \
         is one JSON-RPC message, answered with JSON. Each request brings its API key, as \
         Authorization: Bearer <KEY>{header}; the server's own credentials serve those without \
         one only with --key-from-env. Requests from browser origins other than localhost's are \
         refused, unless --allowed-origins lists them. GET /health answers {{\"status\", \"version\"}}."
    )
}

/// The toolsets `[context.cli_mcp]` of perseid.toml defines, for `--toolsets`' help.
fn toolsets_help(schema: Option<&Schema>) -> String {
    let config = schema
        .map(|schema| schema.mcp().clone())
        .unwrap_or_default();
    let defaults = strings(&config["default_toolsets"]);
    let names: Vec<String> = config["toolsets"]
        .as_object()
        .into_iter()
        .flatten()
        .map(|(name, _)| match defaults.contains(name) {
            true => format!("{name} (default)"),
            false => name.clone(),
        })
        .collect();
    match names.is_empty() {
        true => "Serve the tools of these toolsets, or all with hidden and deprecated ones".into(),
        false => format!(
            "Serve the tools of these toolsets, or all with hidden and deprecated ones: {}",
            names.join(", ")
        ),
    }
}

/// How a tool's `body` reaches its command.
#[derive(Clone, Debug, PartialEq)]
enum BodyArg {
    /// `--data`, as JSON.
    Json,
    /// The path of a file, given to this flag.
    File(&'static str),
}

#[derive(Clone, Debug)]
struct Param {
    property: String,
    arg: String,
    positional: bool,
    required: bool,
}

/// How a list continues, by the property that takes it: its pagination in the schema.
#[derive(Clone, Debug, PartialEq)]
enum Paging {
    /// Page numbers.
    Page(String),
    /// How many items to skip.
    Offset(String),
    /// A field of the last item, such as `id` for `starting_after`.
    Item(String, String),
    /// A cursor the page's response gives.
    Cursor(String),
    /// None: a larger `max_items`.
    Unknown,
}

/// An operation, as a tool.
#[derive(Clone, Debug)]
struct Tool {
    name: String,
    words: Vec<String>,
    title: String,
    description: String,
    input: Value,
    /// The schema of what the command prints; `None` when it prints nothing.
    response: Option<Value>,
    annotations: Value,
    read: bool,
    params: Vec<Param>,
    body: Option<(String, BodyArg, bool)>,
    max_items: Option<String>,
    jq: Option<String>,
    output: String,
    paging: Paging,
    /// Deprecated, or `hidden` in `[context.cli_mcp.operations]`: served only when asked for.
    hidden: bool,
}

/// The tool property of a parameter's argument: `--per-page` is `per_page`, `<THING_ID>`
/// `thing_id`.
fn property(arg: &str) -> String {
    arg.trim_start_matches("--")
        .trim_matches(['<', '>'])
        .to_lowercase()
        .replace('-', "_")
}

fn free(name: &str, taken: &Map<String, Value>) -> String {
    match taken.contains_key(name) {
        true => format!("request_{name}"),
        false => name.to_owned(),
    }
}

/// A tool name of `[A-Za-z0-9_.-]`, as MCP requires: `things list-all` is `things_list_all`.
/// It also keys the operations of `[context.cli]` and `[context.cli_mcp]` in perseid.toml.
pub(super) fn tool_name(words: &str) -> String {
    words
        .chars()
        .map(|c| match c.is_ascii_alphanumeric() || c == '.' {
            true => c,
            false => '_',
        })
        .collect()
}

impl Tool {
    /// The tool of an operation, with what `[context.cli_mcp.operations.<tool>]` overrides:
    /// `name`, `description`, `title`, `annotations` (merged) and `hidden`.
    fn new(schema: &Schema, entry: &Value, overrides: &Value) -> Option<Self> {
        let words = entry["command"].as_str()?;
        let input = schema.describe(words, false)?;
        let output = schema.describe(words, true)?;
        if output["streaming"] == true {
            return None;
        }
        let method = entry["method"].as_str().unwrap_or_default();
        let mut properties = Map::new();
        let mut required = Vec::new();
        let mut params = Vec::new();
        let declared = input["parameters"]["properties"].as_object();
        let needed = &input["parameters"]["required"];
        for (arg, schema) in declared.into_iter().flatten() {
            let mut schema = schema.clone();
            let location = schema["in"].as_str().unwrap_or_default().to_owned();
            if let Some(map) = schema.as_object_mut() {
                map.remove("in");
                map.remove("name");
            }
            if schema["format"] == "binary" {
                let about = schema["description"].as_str().unwrap_or("A file");
                schema = json!({"type": "string", "description": format!("{about} (the path of a local file)")});
            }
            let param = Param {
                property: property(arg),
                arg: arg.clone(),
                positional: location == "path",
                required: needed
                    .as_array()
                    .is_some_and(|names| names.contains(&Value::String(arg.clone()))),
            };
            if param.required {
                required.push(Value::String(param.property.clone()));
            }
            properties.insert(param.property.clone(), schema);
            params.push(param);
        }
        let body = input.get("body").map(|body| {
            let name = free("body", &properties);
            let needed = body["x-required"] == true;
            let (kind, schema) = match body["x-content"].as_str() {
                Some("binary") => {
                    let taken = params.iter().any(|p| p.arg == "--file");
                    let flag = if taken { "body-file" } else { "file" };
                    let about = "The request body: the path of a local file";
                    (
                        BodyArg::File(flag),
                        json!({"type": "string", "description": about}),
                    )
                }
                _ => {
                    let mut schema = body.clone();
                    if let Some(map) = schema.as_object_mut() {
                        map.remove("x-required");
                        map.remove("x-content");
                        map.entry("description")
                            .or_insert_with(|| "The request body".into());
                    }
                    (BodyArg::Json, schema)
                }
            };
            if needed {
                required.push(Value::String(name.clone()));
            }
            properties.insert(name.clone(), schema);
            (name, kind, needed)
        });
        let paginated = output["paginated"] == true;
        let max_items = paginated.then(|| {
            let name = free("max_items", &properties);
            let about = format!("Stop after this many items ({DEFAULT_MAX_ITEMS} by default)");
            properties.insert(
                name.clone(),
                json!({"type": "integer", "minimum": 1, "description": about}),
            );
            name
        });
        let kind = output["output"].as_str().unwrap_or("json").to_owned();
        let jq = matches!(kind.as_str(), "json" | "jsonl").then(|| {
            let name = free("jq", &properties);
            let about = match paginated {
                true => "jq filter over the items, to keep what is needed: `.[] | {id, name}`",
                false => "jq filter over the result, to keep what is needed: `{id, status}`",
            };
            properties.insert(
                name.clone(),
                json!({"type": "string", "description": about}),
            );
            name
        });
        let mut input_schema = json!({
            "type": "object",
            "properties": properties,
            "required": required,
            "additionalProperties": false,
        });
        if let Some(defs) = input.get("$defs") {
            input_schema["$defs"] = defs.clone();
        }
        let pagination = &output["pagination"];
        let paging = match (pagination["style"].as_str(), pagination["arg"].as_str()) {
            (Some("page"), Some(arg)) => Paging::Page(property(arg)),
            (Some("offset"), Some(arg)) => Paging::Offset(property(arg)),
            (Some("cursor"), Some(arg)) => match pagination["item"].as_str() {
                Some(field) => Paging::Item(property(arg), field.to_owned()),
                None => Paging::Cursor(property(arg)),
            },
            _ => Paging::Unknown,
        };
        let summary = entry["summary"].as_str().unwrap_or_default().trim();
        let over = &overrides[tool_name(words)];
        let mut description = over["description"].as_str().unwrap_or(summary).to_owned();
        if let Some(name) = &max_items {
            description.push_str(&format!(
                "\n\nReturns {{items, has_more, next}}: at most `{name}` items, and the arguments \
                 that fetch the next ones."
            ));
        }
        description.push_str(&format!(
            "\n\n`{method} {}`",
            entry["path"].as_str().unwrap_or_default()
        ));
        let response = match kind.as_str() {
            "none" => None,
            "file" => Some(json!({"type": "object", "properties": {
                "bytes": {"type": "integer"}, "content_type": {"type": "string"}}})),
            _ => {
                let mut response = output["response"].clone();
                if let (Some(defs), Some(map)) = (output.get("$defs"), response.as_object_mut()) {
                    map.insert("$defs".into(), defs.clone());
                }
                Some(response)
            }
        };
        let verb = words.rsplit(' ').next().unwrap_or_default();
        let mut annotations = annotations(method, verb);
        if let (Some(into), Some(from)) =
            (annotations.as_object_mut(), over["annotations"].as_object())
        {
            into.extend(from.clone());
        }
        Some(Self {
            name: over["name"]
                .as_str()
                .map_or_else(|| tool_name(words), str::to_owned),
            words: words.split(' ').map(str::to_owned).collect(),
            title: over["title"]
                .as_str()
                .map_or_else(|| title(summary, words), str::to_owned),
            description,
            input: input_schema,
            response,
            annotations,
            read: matches!(method, "GET" | "HEAD"),
            params,
            body,
            max_items,
            jq,
            output: kind,
            paging,
            hidden: output["deprecated"] == true || over["hidden"] == true,
        })
    }

    /// The tool as `tools/list` gives it to a client of `dialect`; `structured`, with its
    /// `outputSchema`.
    fn definition(&self, dialect: Dialect, structured: bool) -> Value {
        let mut definition = json!({
            "name": self.name,
            "title": self.title,
            "description": self.description,
            "inputSchema": lower(&self.input, dialect, false),
            "annotations": self.annotations,
        });
        if let Some(schema) = self.output_schema().filter(|_| structured) {
            definition["outputSchema"] = schema;
        }
        definition
    }

    /// What `structuredContent` holds: the response when it is an object, else under `result`;
    /// for lists `{items, has_more, next, hint}`; with `jq`, its output under `jq` instead.
    fn output_schema(&self) -> Option<Value> {
        let lowered = lower(self.response.as_ref()?, Dialect::Inline, true);
        let mut schema = match (&self.max_items, lowered["type"] == "object") {
            (Some(_), _) => json!({"type": "object", "properties": {
                "items": {"type": "array", "items": lowered},
                "has_more": {"type": "boolean"},
                "next": {"type": ["object", "null"],
                         "description": "The arguments that fetch the items after these"},
                "hint": {"type": "string"},
            }}),
            (None, true) => lowered,
            (None, false) => json!({"type": "object", "properties": {"result": lowered}}),
        };
        if let Some(name) = &self.jq {
            let about =
                format!("The output of `{name}`, when the call passed one, instead of the rest");
            schema["properties"]["jq"] = json!({"description": about});
        }
        Some(schema)
    }

    /// The command line of a call: its words, flags, `--format json`, the server's own options,
    /// then the positional arguments after `--`. Lists ask for one item more than `max_items`,
    /// which tells whether more follow.
    fn argv(
        &self,
        args: &Map<String, Value>,
        file: Option<&PathBuf>,
    ) -> Result<Vec<String>, CliError> {
        let usage = |message: String| CliError::usage(message);
        let mut flags = Vec::new();
        for (key, value) in args.iter().filter(|(_, value)| !value.is_null()) {
            if Some(key) == self.max_items.as_ref() {
                let count = value
                    .as_u64()
                    .filter(|count| *count > 0)
                    .ok_or_else(|| usage(format!("{key}: expected a positive integer")))?;
                flags.push(format!("--max-items={}", count + 1));
                continue;
            }
            if Some(key) == self.jq.as_ref() {
                continue;
            }
            if let Some((name, kind, _)) = self.body.as_ref().filter(|(name, ..)| name == key) {
                match kind {
                    BodyArg::Json => flags.push(format!("--data={}", parsed(value))),
                    BodyArg::File(flag) => {
                        let path = value
                            .as_str()
                            .ok_or_else(|| usage(format!("{name}: expected the path of a file")))?;
                        flags.push(format!("--{flag}={path}"));
                    }
                }
                continue;
            }
            let Some(param) = self.params.iter().find(|p| &p.property == key) else {
                let known = self.properties();
                let close = suggest(key, &known)
                    .map(|name| format!("did you mean `{name}`? "))
                    .unwrap_or_default();
                return Err(usage(format!(
                    "unknown argument `{key}`: {close}expected one of {}",
                    known.join(", ")
                )));
            };
            match (param.positional, value) {
                (true, _) => {}
                (false, Value::Array(items)) => {
                    flags.extend(
                        items
                            .iter()
                            .map(|item| format!("{}={}", param.arg, text(item))),
                    );
                }
                (false, value) => flags.push(format!("{}={}", param.arg, text(value))),
            }
        }
        let given = |name: &str| args.get(name).is_some_and(|value| !value.is_null());
        let mut missing: Vec<&str> = self
            .params
            .iter()
            .filter(|p| p.required && !given(&p.property))
            .map(|p| p.property.as_str())
            .collect();
        if let Some((name, _, true)) = &self.body {
            if !given(name) {
                missing.push(name);
            }
        }
        if !missing.is_empty() {
            return Err(usage(format!(
                "missing required arguments: {}",
                missing.join(", ")
            )));
        }
        if let Some(name) = &self.max_items {
            if !given(name) {
                flags.push(format!("--max-items={}", DEFAULT_MAX_ITEMS + 1));
            }
        }
        if let Some(path) = file {
            flags.push(format!("--output={}", path.display()));
        }
        flags.push("--format=json".to_owned());
        let positionals = self.positionals(args);
        let mut argv: Vec<String> = self.words.clone();
        argv.extend(flags);
        if !positionals.is_empty() {
            argv.push("--".to_owned());
            argv.extend(positionals);
        }
        Ok(argv)
    }

    fn properties(&self) -> Vec<&str> {
        let mut known: Vec<&str> = self.params.iter().map(|p| p.property.as_str()).collect();
        known.extend(self.body.iter().map(|(name, ..)| name.as_str()));
        known.extend(self.max_items.as_deref());
        known.extend(self.jq.as_deref());
        known
    }

    /// Path parameters in the order of the route, lists joined with commas.
    fn positionals(&self, args: &Map<String, Value>) -> Vec<String> {
        self.params
            .iter()
            .filter(|p| p.positional)
            .filter_map(|p| args.get(&p.property).filter(|value| !value.is_null()))
            .map(|value| match value {
                Value::Array(items) => items.iter().map(text).collect::<Vec<_>>().join(","),
                value => text(value),
            })
            .collect()
    }

    /// The items a list printed, as `{items, has_more, next}`: more follow when the command
    /// printed the extra item it was asked for, or when its page said so.
    fn page(&self, args: &Map<String, Value>, mut items: Vec<Value>, listed: Listed) -> Value {
        let limit = self
            .max_items
            .as_ref()
            .and_then(|name| args.get(name))
            .and_then(Value::as_u64)
            .unwrap_or(DEFAULT_MAX_ITEMS);
        let cut = items.len() as u64 > limit;
        items.truncate(usize::try_from(limit).unwrap_or(usize::MAX));
        let more = cut || listed.more;
        let given = |name: &str| args.get(name).is_some_and(|value| !value.is_null());
        let number = |name: &str| args.get(name).and_then(Value::as_u64);
        let next = match &self.paging {
            _ if !more => None,
            Paging::Page(name) if !cut => number(name).map(|page| json!({name: page + 1})),
            Paging::Offset(name) => {
                Some(json!({name: number(name).unwrap_or(0) + items.len() as u64}))
            }
            Paging::Item(name, field) => after(name, field, &items),
            Paging::Cursor(name) if !cut && given(name) => {
                listed.cursor.map(|cursor| json!({name: cursor}))
            }
            _ => None,
        };
        let mut page = json!({"items": items, "has_more": more, "next": next});
        if more && page["next"].is_null() {
            let max = self.max_items.as_deref().unwrap_or("max_items");
            page["hint"] = format!(
                "More items follow: pass a larger `{max}`, or narrow the list with its filters"
            )
            .into();
        }
        page
    }
}

/// The arguments that fetch the items after the last of `items`, by its `field`.
fn after(name: &str, field: &str, items: &[Value]) -> Option<Value> {
    let cursor = &items.last()?[field];
    (!cursor.is_null()).then(|| json!({name: cursor}))
}

/// A body some clients send as a JSON string: the object or array it holds.
fn parsed(value: &Value) -> Value {
    match value {
        Value::String(text) => match serde_json::from_str::<Value>(text) {
            Ok(inner @ (Value::Object(_) | Value::Array(_))) => inner,
            _ => value.clone(),
        },
        other => other.clone(),
    }
}

/// A scalar as the command line takes it; objects and arrays as JSON.
fn text(value: &Value) -> String {
    match value {
        Value::String(text) => text.clone(),
        other => other.to_string(),
    }
}

/// The summary, when short enough for a title, else the command's words.
fn title(summary: &str, words: &str) -> String {
    let summary = summary.trim_end_matches('.');
    if !summary.is_empty() && summary.len() <= 60 && !summary.contains('\n') {
        return summary.to_owned();
    }
    let mut chars = words.chars();
    chars
        .next()
        .map(|first| first.to_uppercase().chain(chars).collect())
        .unwrap_or_default()
}

/// What the HTTP method and the command's verb say of an operation, as hints: clients must not
/// trust them. Creating is not destructive; replacing, updating, deleting and archiving are.
fn annotations(method: &str, verb: &str) -> Value {
    match method {
        "GET" | "HEAD" => {
            json!({"readOnlyHint": true, "idempotentHint": true, "openWorldHint": true})
        }
        "DELETE" | "PUT" => {
            json!({"readOnlyHint": false, "destructiveHint": true, "idempotentHint": true, "openWorldHint": true})
        }
        "PATCH" => {
            json!({"readOnlyHint": false, "destructiveHint": true, "idempotentHint": false, "openWorldHint": true})
        }
        _ => json!({"readOnlyHint": false, "destructiveHint": DESTRUCTIVE.contains(&verb),
                    "idempotentHint": false, "openWorldHint": true}),
    }
}

/// The tools of the schema's operations, the names `[context.cli_mcp.operations.<tool>] name`
/// gives checked: of `[A-Za-z0-9_.-]`, at most [`MAX_TOOL_NAME`] long, and each tool's own.
fn tools(schema: &Schema) -> Result<Vec<Tool>, CliError> {
    let overrides = &schema.mcp()["operations"];
    let tools: Vec<Tool> = (schema.index(&[]).iter())
        .filter_map(|entry| Tool::new(schema, entry, overrides))
        .collect();
    let mut owners: HashMap<&str, &Tool> = HashMap::new();
    for tool in &tools {
        let key = tool_name(&tool.words.join(" "));
        let name = tool.name.as_str();
        let given = &overrides[&key]["name"];
        let valid = (1..=MAX_TOOL_NAME).contains(&name.len())
            && (name.chars()).all(|c| c.is_ascii_alphanumeric() || matches!(c, '_' | '.' | '-'));
        if !(given.is_null() || (given.is_string() && valid)) {
            return Err(CliError::internal(format!(
                "[context.cli_mcp.operations.{key}] name = {given}: a tool name is 1 to \
                 {MAX_TOOL_NAME} of A-Z, a-z, 0-9, _, . and -"
            )));
        }
        if let Some(other) = owners.insert(name, tool) {
            return Err(CliError::internal(format!(
                "two tools are named {name}, of `{}` and `{}`: [context.cli_mcp.operations.<tool>] \
                 name gives one another",
                other.words.join(" "),
                tool.words.join(" ")
            )));
        }
    }
    Ok(tools)
}

/// Checks the names of the tools, as `mcp` does when it starts: generated code's tests call it.
pub fn check(app: &App) -> Result<(), CliError> {
    tools(&Schema::parse(app.schema)?).map(drop)
}

/// `*` matches any run of characters, `?` any one.
fn glob(pattern: &str, name: &str) -> bool {
    let (pattern, name): (Vec<char>, Vec<char>) =
        (pattern.chars().collect(), name.chars().collect());
    let (mut p, mut n) = (0, 0);
    let mut star: Option<(usize, usize)> = None;
    while n < name.len() {
        if p < pattern.len() && (pattern[p] == '?' || pattern[p] == name[n]) {
            p += 1;
            n += 1;
        } else if p < pattern.len() && pattern[p] == '*' {
            star = Some((p, n));
            p += 1;
        } else if let Some((at, from)) = star {
            p = at + 1;
            n = from + 1;
            star = Some((at, from + 1));
        } else {
            return false;
        }
    }
    pattern[p..].iter().all(|c| *c == '*')
}

fn globs(args: &ArgMatches, id: &str) -> Vec<String> {
    args.get_many::<String>(id)
        .into_iter()
        .flatten()
        .map(|pattern| pattern.trim().to_owned())
        .filter(|pattern| !pattern.is_empty())
        .collect()
}

/// Which tools a server serves. `--tools` names them, else toolsets do: those `--toolsets` names
/// (`all`, hidden and deprecated tools too), else the `default_toolsets` of `[context.cli_mcp]`,
/// with the tools no toolset holds. `--exclude-tools` and `--read-only` win over both.
struct Selection {
    toolsets: Vec<(String, Vec<String>)>,
    chosen: Option<Vec<String>>,
    all: bool,
    included: Vec<String>,
    excluded: Vec<String>,
    read_only: bool,
}

impl Selection {
    fn new(config: &Value, args: &ArgMatches) -> Result<Self, CliError> {
        let toolsets: Vec<(String, Vec<String>)> = config["toolsets"]
            .as_object()
            .into_iter()
            .flatten()
            .map(|(name, globs)| (name.clone(), strings(globs)))
            .collect();
        let asked = globs(args, "toolsets");
        let all = asked.iter().any(|name| name == "all");
        let chosen = match asked.is_empty() {
            true => config.get("default_toolsets").map(strings),
            false => Some(asked),
        };
        let known: Vec<&str> = toolsets.iter().map(|(name, _)| name.as_str()).collect();
        let unknown = chosen
            .iter()
            .flatten()
            .find(|name| *name != "all" && !known.contains(&name.as_str()));
        if let Some(name) = unknown {
            let close = suggest(name, &known)
                .map(|close| format!("did you mean {close}? "))
                .unwrap_or_default();
            return Err(CliError::usage(format!(
                "--toolsets: no toolset `{name}`: {close}expected all or one of {}",
                known.join(", ")
            )));
        }
        Ok(Self {
            toolsets,
            chosen,
            all,
            included: globs(args, "tools"),
            excluded: globs(args, "exclude-tools"),
            read_only: args.get_flag("read-only"),
        })
    }

    fn serves(&self, tool: &Tool) -> bool {
        let matches = |globs: &[String]| globs.iter().any(|p| glob(p, &tool.name));
        if (self.read_only && !tool.read) || matches(&self.excluded) {
            return false;
        }
        if !self.included.is_empty() {
            return matches(&self.included);
        }
        if self.all {
            return true;
        }
        if tool.hidden {
            return false;
        }
        let Some(chosen) = &self.chosen else {
            return true;
        };
        let holding: Vec<&String> = (self.toolsets.iter())
            .filter(|(_, globs)| matches(globs))
            .map(|(name, _)| name)
            .collect();
        holding.is_empty() || holding.iter().any(|name| chosen.contains(name))
    }
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(str::to_owned)
        .collect()
}

/// A JSON-RPC error.
pub(super) struct RpcError {
    code: i64,
    message: String,
    data: Option<Value>,
}

impl RpcError {
    pub(super) fn new(code: i64, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
            data: None,
        }
    }

    /// `UnsupportedProtocolVersionError`, listing the revisions served.
    pub(super) fn unsupported(requested: Value) -> Self {
        let mut supported = vec![PROTOCOL_VERSION];
        supported.extend(LEGACY_VERSIONS);
        Self {
            code: UNSUPPORTED_VERSION,
            message: "Unsupported protocol version".into(),
            data: Some(json!({"supported": supported, "requested": requested})),
        }
    }
}

/// The server: its tools, and the options of its command line each call inherits. Over HTTP, a
/// clone serves each request ([`Server::for_request`]).
#[derive(Clone)]
pub struct Server {
    tools: Rc<[Tool]>,
    /// The names of the tools `--read-only`, `--tools` and `--exclude-tools` leave out.
    left_out: Rc<[String]>,
    inherited: Vec<String>,
    pub(super) name: String,
    version: String,
    instructions: String,
    pub(super) debug: bool,
    /// The calls started, which name their downloads.
    calls: Rc<Cell<u64>>,
    /// `--client`, which wins over the client's own name.
    client: Option<Dialect>,
    /// The dialect of the client that named itself.
    named: Option<Dialect>,
    /// The revision `initialize` agreed on.
    negotiated: Option<&'static str>,
    max_chars: usize,
    list: bool,
    /// `--port` and the other options of HTTP.
    #[cfg(feature = "mcp-http")]
    http: Option<super::mcp_http::Options>,
}

impl Server {
    pub(super) fn new(
        session: &Session,
        args: &ArgMatches,
        globals: &Globals,
    ) -> Result<Self, CliError> {
        let schema = Schema::parse(session.app.schema)?;
        let config = schema.mcp();
        let selection = Selection::new(config, args)?;
        #[cfg(feature = "mcp-http")]
        let http = super::mcp_http::Options::new(args, &schema);
        let tools = tools(&schema)?;
        let (tools, left_out): (Vec<Tool>, Vec<Tool>) =
            tools.into_iter().partition(|tool| selection.serves(tool));
        let left_out = left_out.into_iter().map(|tool| tool.name).collect();
        let mut inherited = Vec::new();
        let mut pass = |flag: &str, value: Option<String>| {
            if let Some(value) = value {
                inherited.push(format!("--{flag}={value}"));
            }
        };
        pass("profile", globals.profile.clone());
        pass("api-key", globals.api_key.clone());
        pass("base-url", globals.base_url.clone());
        pass("retries", globals.retries.map(|n| n.to_string()));
        pass(
            "timeout",
            globals.timeout.map(|t| t.as_secs_f64().to_string()),
        );
        for (flag, on) in [
            ("no-retry", globals.no_retry),
            ("debug", globals.debug),
            ("dry-run", globals.dry_run),
            ("allow-unknown-fields", globals.allow_unknown_fields),
        ] {
            if on {
                inherited.push(format!("--{flag}"));
            }
        }
        let name = session.app.name.to_owned();
        let about = session
            .cmd
            .get_about()
            .map_or_else(|| format!("The {name} API"), ToString::to_string);
        let own = config["instructions"]
            .as_str()
            .map(|text| format!("{}\n\n", text.trim()))
            .unwrap_or_default();
        let instructions = format!(
            "{own}{about}: a tool per API operation, running the `{name}` command of the same name. \
             Results are the API's JSON: pass `jq` to keep only the fields needed, such as \
             `.[] | {{id, name}}` on a list. Lists return {{items, has_more, next}}: call again \
             with `next`'s arguments for more. Errors return isError with {{\"error\": {{kind, \
             status, message, retryable, errors}}}}: `errors` lists each invalid field of a \
             body, which is checked against its schema before it is sent."
        );
        Ok(Self {
            tools: tools.into(),
            left_out,
            inherited,
            version: session.cmd.get_version().unwrap_or("0.0.0").to_owned(),
            name,
            instructions,
            debug: globals.debug,
            calls: Rc::default(),
            client: args
                .get_one::<String>("client")
                .map(|name| Dialect::of(name)),
            named: None,
            negotiated: None,
            max_chars: args
                .get_one::<usize>("max-chars")
                .copied()
                .unwrap_or(DEFAULT_MAX_CHARS),
            list: args.get_flag("list"),
            #[cfg(feature = "mcp-http")]
            http,
        })
    }

    /// The server of one HTTP request: no client named yet, the legacy revision `version` of its
    /// `MCP-Protocol-Version`, and its API key `key` in place of the server's, when given.
    #[cfg(feature = "mcp-http")]
    pub(super) fn for_request(&self, key: Option<&str>, version: Option<&'static str>) -> Self {
        let mut server = self.clone();
        server.named = None;
        server.negotiated = version;
        if let Some(key) = key {
            server
                .inherited
                .retain(|arg| !arg.starts_with("--api-key="));
            server.inherited.push(format!("--api-key={key}"));
        }
        server
    }

    fn definitions(&self, structured: bool) -> Vec<Value> {
        let dialect = self.client.or(self.named).unwrap_or(Dialect::Inline);
        self.tools
            .iter()
            .map(|tool| tool.definition(dialect, structured))
            .collect()
    }

    /// Answers each request of stdin on `out`, one JSON-RPC message per line, until stdin ends
    /// and the calls in flight are answered. Calls run side by side on one current-thread
    /// runtime; `notifications/cancelled` drops one, which ends its requests, unanswered.
    pub(super) fn serve<F, Fut>(
        mut self,
        session: &mut Session,
        out: &mut dyn Write,
        dispatch: &F,
    ) -> Result<(), CliError>
    where
        F: Fn(Ctx, ArgMatches) -> Fut,
        Fut: Future<Output = Result<(), CliError>>,
    {
        if self.list {
            let tools = Value::Array(self.definitions(true));
            writeln!(out, "{}", serde_json::to_string_pretty(&tools)?)?;
            return Ok(out.flush()?);
        }
        if self.debug {
            writeln!(
                session.stderr,
                "debug: mcp: {} tools, protocol {PROTOCOL_VERSION} (and {} after initialize)",
                self.tools.len(),
                LEGACY_VERSIONS.join(", ")
            )?;
        }
        #[cfg(feature = "mcp-http")]
        if let Some(options) = self.http.take() {
            return super::mcp_http::serve(self, session, options, dispatch);
        }
        let stdin = std::mem::replace(&mut session.stdin, Box::new(std::io::empty()));
        let (sender, mut lines) = tokio::sync::mpsc::unbounded_channel();
        std::thread::spawn(move || {
            for line in BufReader::new(stdin).lines() {
                if sender.send(line).is_err() {
                    break;
                }
            }
        });
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()?;
        runtime.block_on(async {
            let mut calls = InFlight(Vec::new());
            let mut open = true;
            while open || !calls.0.is_empty() {
                let event = std::future::poll_fn(|cx| match calls.poll_done(cx) {
                    Poll::Ready((id, result)) => Poll::Ready(Event::Done(id, result)),
                    Poll::Pending if open => lines.poll_recv(cx).map(Event::Line),
                    Poll::Pending => Poll::Pending,
                })
                .await;
                let response = match event {
                    Event::Done(id, result) => Some(reply(id, Ok(result))),
                    Event::Line(None) => {
                        open = false;
                        None
                    }
                    Event::Line(Some(line)) => {
                        let line = line?;
                        if line.trim().is_empty() {
                            continue;
                        }
                        match serde_json::from_str::<Value>(&line) {
                            Err(error) => Some(reply(
                                Value::Null,
                                Err(RpcError::new(PARSE_ERROR, format!("Parse error: {error}"))),
                            )),
                            Ok(message) => match self.handle(message, session) {
                                Handled::Reply(response) => Some(response),
                                Handled::Start(id, call) => {
                                    calls.0.push((id, Box::pin(call.run(dispatch))));
                                    None
                                }
                                Handled::Cancel(id) => {
                                    calls.0.retain(|(running, _)| *running != id);
                                    None
                                }
                                Handled::Nothing => None,
                            },
                        }
                    }
                };
                if let Some(response) = response {
                    writeln!(out, "{response}")?;
                    out.flush()?;
                }
            }
            Ok(())
        })
    }

    /// What to do with one message: answer it, start a call, cancel one, or nothing (other
    /// notifications, responses).
    pub(super) fn handle(&mut self, message: Value, session: &Session) -> Handled {
        let Value::Object(message) = message else {
            let error = RpcError::new(INVALID_REQUEST, "Invalid Request: expected an object");
            return Handled::Reply(reply(Value::Null, Err(error)));
        };
        let Some(method) = message.get("method").and_then(Value::as_str) else {
            return Handled::Nothing;
        };
        let params = message.get("params").cloned().unwrap_or_else(|| json!({}));
        let Some(id) = message.get("id").cloned() else {
            return match (method, params.get("requestId")) {
                ("notifications/cancelled", Some(id)) => Handled::Cancel(id.clone()),
                _ => Handled::Nothing,
            };
        };
        if !(id.is_string() || id.is_number()) {
            let error = RpcError::new(
                INVALID_REQUEST,
                "Invalid Request: the id must be a string or a number",
            );
            return Handled::Reply(reply(Value::Null, Err(error)));
        }
        match self.request(method, &params, session) {
            Ok(Answer::Now(result)) => Handled::Reply(reply(id, Ok(result))),
            Ok(Answer::Later(call)) => Handled::Start(id, call),
            Err(error) => Handled::Reply(reply(id, Err(error))),
        }
    }

    fn request(
        &mut self,
        method: &str,
        params: &Value,
        session: &Session,
    ) -> Result<Answer, RpcError> {
        if !params.is_object() {
            return Err(RpcError::new(INVALID_PARAMS, "params must be an object"));
        }
        if let Some(error) = malformed(params) {
            return Err(error);
        }
        let meta = &params["_meta"];
        let modern = meta[VERSION_KEY] == PROTOCOL_VERSION;
        if let Some(name) = meta[CLIENT_INFO_KEY]["name"].as_str() {
            self.named = Some(Dialect::of(name));
        }
        let structured = modern || self.negotiated.is_none_or(|v| v >= STRUCTURED_SINCE);
        let mut result = match method {
            "initialize" => self.initialize(params),
            "server/discover" => {
                let mut supported = vec![PROTOCOL_VERSION];
                supported.extend(LEGACY_VERSIONS);
                json!({
                    "supportedVersions": supported,
                    "capabilities": {"tools": {"listChanged": false}},
                    "instructions": self.instructions,
                    "ttlMs": TTL_MS,
                    "cacheScope": "public",
                })
            }
            "ping" => json!({}),
            "tools/list" => {
                let tools = self.definitions(structured);
                match modern {
                    true => json!({"tools": tools, "ttlMs": TTL_MS, "cacheScope": "public"}),
                    false => json!({"tools": tools}),
                }
            }
            "tools/call" => {
                let info = (modern).then(|| self.info());
                return self.call(params, structured, info, session);
            }
            other => {
                return Err(RpcError::new(
                    METHOD_NOT_FOUND,
                    format!("Method not found: {other}"),
                ))
            }
        };
        if modern || method == "server/discover" {
            complete(&mut result, self.info());
        }
        Ok(Answer::Now(result))
    }

    pub(super) fn info(&self) -> Value {
        json!({"name": self.name, "version": self.version})
    }

    /// The handshake of the legacy revisions: the client's when supported, else the latest.
    fn initialize(&mut self, params: &Value) -> Value {
        let requested = params["protocolVersion"].as_str().unwrap_or_default();
        let version = LEGACY_VERSIONS
            .iter()
            .find(|v| **v == requested)
            .unwrap_or(&LEGACY_VERSIONS[0]);
        self.negotiated = Some(version);
        if let Some(name) = params["clientInfo"]["name"].as_str() {
            self.named = Some(Dialect::of(name));
        }
        json!({
            "protocolVersion": version,
            "capabilities": {"tools": {"listChanged": false}},
            "serverInfo": self.info(),
            "instructions": self.instructions,
        })
    }

    /// A tool call, checked and ready to run, or its immediate failure; `info` completes the
    /// result for the requests that carry their version.
    fn call(
        &mut self,
        params: &Value,
        structured: bool,
        info: Option<Value>,
        session: &Session,
    ) -> Result<Answer, RpcError> {
        let name = params["name"].as_str().unwrap_or_default();
        let Some(tool) = self.tools.iter().find(|tool| tool.name == name).cloned() else {
            let names: Vec<&str> = self.tools.iter().map(|tool| tool.name.as_str()).collect();
            let why = match self.left_out.iter().any(|left| left == name) {
                true => {
                    ": this server leaves it out (its toolsets, --toolsets, --tools, --exclude-tools, --read-only)".into()
                }
                false => suggest(name, &names)
                    .map(|close| format!(": did you mean {close}?"))
                    .unwrap_or_default(),
            };
            return Err(RpcError::new(
                INVALID_PARAMS,
                format!("Unknown tool: {name}{why}"),
            ));
        };
        let args = match &params["arguments"] {
            Value::Null => Map::new(),
            Value::Object(args) => args.clone(),
            _ => return Err(RpcError::new(INVALID_PARAMS, "arguments must be an object")),
        };
        let done = |mut result: Value| {
            if let Some(info) = &info {
                complete(&mut result, info.clone());
            }
            Ok(Answer::Now(result))
        };
        let jq = match tool.jq.as_ref().and_then(|name| args.get(name)) {
            None | Some(Value::Null) => None,
            Some(Value::String(code)) => match Jq::compile(code) {
                Ok(jq) => Some(jq),
                Err(error) => return done(failed(&jq_error(&error, &tool))),
            },
            Some(_) => {
                let name = tool.jq.as_deref().unwrap_or("jq");
                return done(failed(&CliError::usage(format!(
                    "{name}: expected a string"
                ))));
            }
        };
        let number = self.calls.get() + 1;
        self.calls.set(number);
        let file = (tool.output == "file").then(|| {
            std::env::temp_dir().join(format!(
                "{}-mcp-{}-{number}.download",
                self.name,
                std::process::id(),
            ))
        });
        let argv = match tool.argv(&args, file.as_ref()) {
            Ok(argv) => argv,
            Err(error) => return done(failed(&error)),
        };
        let mut command_line = vec![self.name.clone()];
        command_line.extend(argv.iter().take(tool.words.len()).cloned());
        command_line.extend(self.inherited.iter().cloned());
        command_line.extend(argv.into_iter().skip(tool.words.len()));
        Ok(Answer::Later(Box::new(Call {
            uri: format!("{}://{}/{number}", self.name, tool.name),
            tool,
            args,
            jq,
            file,
            command_line,
            shape: Shape {
                structured,
                max_chars: self.max_chars,
            },
            info,
            app: session.app,
            cmd: session.cmd.clone(),
            env: session.env.clone(),
            config_dir: session.config_dir.clone(),
            stderr: session.stderr.clone(),
        })))
    }
}

/// The error of a request whose `_meta` names a revision not served, or, for 2026-07-28, lacks
/// the client's capabilities.
pub(super) fn malformed(params: &Value) -> Option<RpcError> {
    let meta = &params["_meta"];
    let served = |version: &str| version == PROTOCOL_VERSION || LEGACY_VERSIONS.contains(&version);
    match meta.get(VERSION_KEY).map(Value::as_str) {
        Some(Some(PROTOCOL_VERSION)) if meta.get(CAPABILITIES_KEY).is_none() => {
            let message = format!("missing _meta[\"{CAPABILITIES_KEY}\"]");
            Some(RpcError::new(INVALID_PARAMS, message))
        }
        Some(Some(version)) if served(version) => None,
        Some(_) => Some(RpcError::unsupported(meta[VERSION_KEY].clone())),
        None => None,
    }
}

/// A message, as [`Server::handle`] takes it.
pub(super) enum Handled {
    Reply(Value),
    Start(Value, Box<Call>),
    Cancel(Value),
    Nothing,
}

/// The result of a request, or the call that will produce it.
enum Answer {
    Now(Value),
    Later(Box<Call>),
}

/// The calls running, by request id: dropping one cancels it.
struct InFlight<T>(Vec<(Value, Pin<Box<T>>)>);

impl<T: Future<Output = Value>> InFlight<T> {
    /// The first call to finish, with its id.
    fn poll_done(&mut self, cx: &mut std::task::Context<'_>) -> Poll<(Value, Value)> {
        let done =
            self.0
                .iter_mut()
                .enumerate()
                .find_map(|(i, (_, call))| match call.as_mut().poll(cx) {
                    Poll::Ready(result) => Some((i, result)),
                    Poll::Pending => None,
                });
        match done {
            Some((i, result)) => Poll::Ready((self.0.swap_remove(i).0, result)),
            None => Poll::Pending,
        }
    }
}

enum Event {
    Line(Option<std::io::Result<String>>),
    Done(Value, Value),
}

/// Completes the result of a request that carried its version.
fn complete(result: &mut Value, info: Value) {
    result["resultType"] = "complete".into();
    result["_meta"] = json!({SERVER_INFO_KEY: info});
}

/// A tool call, with all it needs: calls run side by side, while the server reads stdin.
pub(super) struct Call {
    tool: Tool,
    args: Map<String, Value>,
    jq: Option<Jq>,
    file: Option<PathBuf>,
    command_line: Vec<String>,
    shape: Shape,
    info: Option<Value>,
    uri: String,
    app: App,
    cmd: clap::Command,
    env: HashMap<String, String>,
    config_dir: Option<PathBuf>,
    stderr: Shared,
}

impl Call {
    /// Runs the command it names, in process: the same parsing, validation, credentials and
    /// retries as on the command line.
    pub(super) async fn run<F, Fut>(self, dispatch: &F) -> Value
    where
        F: Fn(Ctx, ArgMatches) -> Fut,
        Fut: Future<Output = Result<(), CliError>>,
    {
        let mut result = self.result(dispatch).await;
        if let Some(info) = &self.info {
            complete(&mut result, info.clone());
        }
        result
    }

    async fn result<F, Fut>(&self, dispatch: &F) -> Value
    where
        F: Fn(Ctx, ArgMatches) -> Fut,
        Fut: Future<Output = Result<(), CliError>>,
    {
        let (mut host, captured) = Host::captured(Vec::new());
        host.env = self.env.clone();
        host.config_dir = self.config_dir.clone();
        let report = Rc::new(Cell::new(None));
        let line = parse(
            self.app,
            self.cmd.clone(),
            self.command_line.clone(),
            host,
            Some(report.clone()),
            |_, _| {},
        );
        let outcome = match line {
            Ok(line) => line.run(dispatch).await,
            Err(failure) => Err(failure),
        };
        let stdout = captured.stdout.text();
        let _ = write!(self.stderr.clone(), "{}", captured.stderr.text());
        let downloaded = self.file.as_ref().and_then(|path| {
            let bytes = std::fs::read(path).ok();
            let _ = std::fs::remove_file(path);
            bytes
        });
        if let Err(failure) = outcome {
            return failed(&failure.into_error());
        }
        if let Some(bytes) = downloaded {
            return self.resource(&stdout, &bytes);
        }
        let (tool, shape) = (&self.tool, &self.shape);
        let printed = stdout.trim();
        let value = match serde_json::from_str::<Value>(printed) {
            _ if printed.is_empty() => return shape.text("No content: the request succeeded."),
            Err(_) => return shape.text(printed),
            Ok(Value::Array(items)) if tool.max_items.is_some() => {
                tool.page(&self.args, items, report.take().unwrap_or_default())
            }
            Ok(value) => value,
        };
        shape.result(tool, value, self.jq.as_ref())
    }

    /// A downloaded file, as an embedded resource, after the `{"path", "bytes", "content_type"}`
    /// the command printed.
    fn resource(&self, printed: &str, bytes: &[u8]) -> Value {
        let (tool, structured) = (&self.tool, self.shape.structured);
        if bytes.len() as u64 > MAX_FILE_BYTES {
            let message = format!(
                "the file is {} bytes, more than the {MAX_FILE_BYTES} an MCP result takes: \
                 download it with the `{}` command and -o FILE",
                bytes.len(),
                tool.words.join(" ")
            );
            return failed(&CliError::usage(message));
        }
        let printed: Value = serde_json::from_str(printed).unwrap_or(Value::Null);
        let mime = printed["content_type"]
            .as_str()
            .unwrap_or("application/octet-stream");
        let summary = json!({"bytes": bytes.len(), "content_type": mime});
        let mut result = json!({
            "content": [
                {"type": "text", "text": summary.to_string()},
                {"type": "resource", "resource": {
                    "uri": self.uri,
                    "mimeType": mime,
                    "blob": base64(bytes),
                }},
            ],
            "isError": false,
        });
        if structured {
            result["structuredContent"] = summary;
        }
        result
    }
}

/// How results reach the client: structured from 2025-06-18 on, cut to `max_chars`.
struct Shape {
    structured: bool,
    max_chars: usize,
}

impl Shape {
    /// A successful call: `value` through `jq`, as text and structured content.
    fn result(&self, tool: &Tool, value: Value, jq: Option<&Jq>) -> Value {
        let value = match jq {
            None => value,
            Some(jq) => {
                let (input, rest) = match (&tool.max_items, value) {
                    (Some(_), Value::Object(mut page)) => {
                        (page.remove("items").unwrap_or_default(), page)
                    }
                    (_, value) => (value, Map::new()),
                };
                let outputs = match jq.run(&input) {
                    Ok(outputs) => outputs,
                    Err(error) => return failed(&jq_error(&error, tool)),
                };
                let output = match <[Value; 1]>::try_from(outputs) {
                    Ok([one]) => one,
                    Err(many) => Value::Array(many),
                };
                let mut filtered = Map::from_iter([("jq".to_owned(), output)]);
                filtered.extend(rest);
                Value::Object(filtered)
            }
        };
        let value = match value {
            Value::Object(_) => value,
            value => json!({"result": value}),
        };
        let value = match self.fit(tool, value) {
            Ok(value) => value,
            Err(error) => return error,
        };
        let mut result =
            json!({"content": [{"type": "text", "text": value.to_string()}], "isError": false});
        if self.structured {
            result["structuredContent"] = value;
        }
        result
    }

    /// What the command printed when it is not JSON.
    fn text(&self, text: &str) -> Value {
        json!({"content": [{"type": "text", "text": text}], "isError": false})
    }

    /// `value`, or when its JSON is longer than `max_chars`, a list's first items, or a failed
    /// result naming the fields to ask for.
    fn fit(&self, tool: &Tool, mut value: Value) -> Result<Value, Value> {
        let length = value.to_string().len();
        if self.max_chars == 0 || length <= self.max_chars {
            return Ok(value);
        }
        let jq = tool.jq.as_deref().unwrap_or("jq");
        let listed = tool.max_items.is_some() && value["items"].is_array();
        if let Some(Value::Array(mut items)) =
            value.get_mut("items").filter(|_| listed).map(Value::take)
        {
            let total = items.len();
            let mut size = 0;
            let kept = items
                .iter()
                .take_while(|item| {
                    size += item.to_string().len() + 1;
                    size <= self.max_chars * 9 / 10
                })
                .count();
            items.truncate(kept);
            let dropped = (total - kept) as u64;
            let next = match &tool.paging {
                Paging::Item(name, field) => after(name, field, &items),
                Paging::Offset(name) => value["next"][name]
                    .as_u64()
                    .map(|offset| json!({name: offset - dropped})),
                _ => None,
            };
            let hint = format!(
                "Cut to {kept} of {total} items, the result being longer than {} characters: \
                 pass `{jq}` to keep only the fields needed, or a smaller `max_items`",
                self.max_chars
            );
            value["items"] = Value::Array(items);
            value["has_more"] = true.into();
            value["next"] = next.unwrap_or_default();
            value["hint"] = hint.into();
            return Ok(value);
        }
        let fields: Vec<&str> = value
            .as_object()
            .map(|map| map.keys().map(String::as_str).collect())
            .unwrap_or_default();
        let message = format!(
            "The result is {length} characters, more than the {} this server returns: pass \
             `{jq}` to keep only the fields needed. Its fields: {}",
            self.max_chars,
            fields.join(", ")
        );
        if tool.read {
            let mut error = compact(&CliError::output(message));
            error["error"]["fields"] = json!(fields);
            return Err(
                json!({"content": [{"type": "text", "text": error.to_string()}], "isError": true}),
            );
        }
        Ok(json!({"result": format!("The request succeeded. {message}")}))
    }
}

/// The error JSON of the command, without the keys it has no value for.
fn compact(error: &CliError) -> Value {
    let mut json = error.to_json();
    if let Some(map) = json["error"].as_object_mut() {
        map.retain(|_, value| !value.is_null());
    }
    json
}

/// A failed `jq`, named as the tool's argument rather than the command line's flag.
fn jq_error(error: &CliError, tool: &Tool) -> CliError {
    let name = tool.jq.as_deref().unwrap_or("jq");
    CliError::usage(error.message().replacen("--jq", &format!("`{name}`"), 1))
}

/// A failed call, whose text is the error JSON of the command.
fn failed(error: &CliError) -> Value {
    json!({"content": [{"type": "text", "text": compact(error).to_string()}], "isError": true})
}

pub(super) fn reply(id: Value, result: Result<Value, RpcError>) -> Value {
    match result {
        Ok(result) => json!({"jsonrpc": "2.0", "id": id, "result": result}),
        Err(error) => {
            let mut body = json!({"code": error.code, "message": error.message});
            if let Some(data) = error.data {
                body["data"] = data;
            }
            json!({"jsonrpc": "2.0", "id": id, "error": body})
        }
    }
}

/// Standard base64, padded.
fn base64(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let byte = |i: usize| u32::from(chunk.get(i).copied().unwrap_or(0));
        let n = byte(0) << 16 | byte(1) << 8 | byte(2);
        for i in 0..4 {
            match i <= chunk.len() {
                true => out.push(char::from(TABLE[(n >> (18 - 6 * i) & 63) as usize])),
                false => out.push('='),
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn part() -> Value {
        json!({
            "resources": {"things": "things"},
            "commands": {
                "things.list": {"resource": "things", "command": "list", "method": "GET",
                    "path": "/things", "summary": "List things", "paginated": true,
                    "pagination": {"style": "cursor", "arg": "--starting-after", "item": "id"},
                    "params": [
                        {"name": "starting_after", "in": "query", "arg": "--starting-after", "required": false, "schema": {"type": "string"}},
                        {"name": "status", "in": "query", "arg": "--status", "required": false,
                         "schema": {"type": "array", "items": {"type": "string"}}},
                    ],
                    "response": {"$ref": "#/$defs/Thing"}},
                "things.pages": {"resource": "things", "command": "pages", "method": "GET",
                    "path": "/pages", "summary": "Pages", "paginated": true,
                    "pagination": {"style": "page", "arg": "--page"},
                    "params": [{"name": "page", "in": "query", "arg": "--page", "required": false, "schema": {"type": "integer"}}]},
                "things.create": {"resource": "things", "command": "create", "method": "POST",
                    "path": "/things/{group}", "summary": "Create a thing",
                    "params": [{"name": "group", "in": "path", "arg": "<GROUP>", "required": true, "schema": {"type": "string"}},
                               {"name": "dry", "in": "query", "arg": "--dry", "required": false, "schema": {"type": "boolean"}}],
                    "body": {"content": "json", "required": true, "schema": {"$ref": "#/$defs/New"}},
                    "response": {"$ref": "#/$defs/Thing"}},
                "things.events": {"resource": "things", "command": "events", "method": "GET",
                    "path": "/events", "summary": "Events", "streaming": true},
                "things.delete": {"resource": "things", "command": "delete", "method": "DELETE",
                    "path": "/things/{id}", "summary": "Delete", "output": "none",
                    "params": [{"name": "id", "in": "path", "arg": "<ID>", "required": true, "schema": {"type": "string"}}]},
                "things.archive": {"resource": "things", "command": "archive", "method": "POST",
                    "path": "/things/{id}/archive", "summary": "Archive",
                    "params": [{"name": "id", "in": "path", "arg": "<ID>", "required": true, "schema": {"type": "string"}}]},
            },
            "$defs": {
                "New": {"type": "object", "required": ["name"], "properties": {"name": {"type": "string"}}},
                "Thing": {"type": "object", "required": ["id"], "properties": {
                    "id": {"type": "string"}, "note": {"type": "string", "nullable": true}}},
            },
        })
    }

    fn schema() -> Schema {
        Schema::parse(&[&part().to_string()]).unwrap()
    }

    const APP: App = App {
        name: "acme",
        env_prefix: "ACME",
        auth: &super::super::auth::ApiKey,
        default_base_url: None,
        default_format: None,
        schema: &[],
    };

    fn tool(words: &str) -> Tool {
        let schema = schema();
        let entry = schema
            .index(&[])
            .into_iter()
            .find(|entry| entry["command"] == words)
            .unwrap();
        Tool::new(&schema, &entry, &Value::Null).unwrap()
    }

    fn args(value: Value) -> Map<String, Value> {
        value.as_object().unwrap().clone()
    }

    #[test]
    fn tools_take_their_parameters_and_body_as_json_schema() {
        let create = tool("things create").definition(Dialect::Refs, true);
        assert_eq!(create["name"], "things_create");
        assert_eq!(create["title"], "Create a thing");
        let input = &create["inputSchema"];
        assert_eq!(input["required"], json!(["group", "body"]));
        assert_eq!(input["properties"]["group"], json!({"type": "string"}));
        assert_eq!(input["properties"]["body"]["required"], json!(["name"]));
        assert_eq!(input["additionalProperties"], false);
        assert_eq!(create["annotations"]["destructiveHint"], false);
        let output = &create["outputSchema"];
        assert_eq!(
            output["properties"]["note"]["type"],
            json!(["string", "null"])
        );
        assert!(output.get("required").is_none());
        assert!(output["properties"]["jq"].is_object());

        let list = tool("things list").definition(Dialect::Inline, true);
        assert_eq!(list["annotations"]["readOnlyHint"], true);
        assert!(list["inputSchema"]["properties"]["max_items"].is_object());
        assert!(list["inputSchema"]["properties"]["jq"].is_object());
        assert_eq!(
            list["outputSchema"]["properties"]["items"]["items"]["properties"]["id"]["type"],
            json!(["string", "null"])
        );
        let delete = tool("things delete").definition(Dialect::Inline, true);
        assert_eq!(delete["annotations"]["destructiveHint"], true);
        assert!(delete.get("outputSchema").is_none());
        assert!(delete["inputSchema"]["properties"].get("jq").is_none());
        let archive = tool("things archive").definition(Dialect::Inline, false);
        assert_eq!(archive["annotations"]["destructiveHint"], true);
        assert!(archive.get("outputSchema").is_none());

        let schema = schema();
        let mut streams = schema
            .index(&[])
            .into_iter()
            .filter(|e| e["command"] == "things events");
        assert!(streams.all(|e| Tool::new(&schema, &e, &Value::Null).is_none()));
    }

    #[test]
    fn calls_become_command_lines() {
        let create = tool("things create");
        let argv = create
            .argv(
                &args(json!({"group": "-g", "dry": true, "body": "{\"name\": \"Lamp\"}"})),
                None,
            )
            .unwrap();
        assert_eq!(
            argv,
            [
                "things",
                "create",
                "--dry=true",
                "--data={\"name\":\"Lamp\"}",
                "--format=json",
                "--",
                "-g"
            ]
        );
        let list = tool("things list");
        let argv = list
            .argv(&args(json!({"status": ["a", "b"], "jq": ".[]"})), None)
            .unwrap();
        assert_eq!(
            argv,
            [
                "things",
                "list",
                "--status=a",
                "--status=b",
                "--max-items=21",
                "--format=json"
            ]
        );
        let missing = create.argv(&args(json!({"group": "g"})), None).unwrap_err();
        assert_eq!(missing.message(), "missing required arguments: body");
        let unknown = list.argv(&args(json!({"stauts": 1})), None).unwrap_err();
        assert_eq!(
            unknown.message(),
            "unknown argument `stauts`: did you mean `status`? expected one of starting_after, status, max_items, jq"
        );
        assert!(list.argv(&args(json!({"max_items": 0})), None).is_err());
    }

    #[test]
    fn lists_say_exactly_how_to_continue() {
        let items = |n: usize| (0..n).map(|i| json!({"id": format!("th_{i}")})).collect();
        let none = Listed::default;
        let list = tool("things list");
        assert_eq!(
            list.page(&args(json!({"max_items": 2})), items(3), none()),
            json!({"items": [{"id": "th_0"}, {"id": "th_1"}], "has_more": true,
                   "next": {"starting_after": "th_1"}})
        );
        let last = list.page(&args(json!({"max_items": 2})), items(2), none());
        assert_eq!(
            (&last["has_more"], &last["next"]),
            (&json!(false), &Value::Null)
        );

        let pages = tool("things pages");
        let more = Listed {
            count: 2,
            more: true,
            cursor: Some("c2".into()),
        };
        let page = pages.page(&args(json!({"page": 3})), items(2), more.clone());
        assert_eq!(page["next"], json!({"page": 4}));
        let mut tokens = pages.clone();
        tokens.paging = Paging::Cursor("page_token".into());
        let page = tokens.page(&args(json!({"page_token": "c1"})), items(2), more.clone());
        assert_eq!(page["next"], json!({"page_token": "c2"}));
        assert!(tokens.page(&Map::new(), items(21), more.clone())["next"].is_null());
        let mut offsets = pages.clone();
        offsets.paging = Paging::Offset("offset".into());
        let page = offsets.page(
            &args(json!({"offset": 40, "max_items": 2})),
            items(3),
            Listed::default(),
        );
        assert_eq!(page["next"], json!({"offset": 42}));
        let page = pages.page(&Map::new(), items(21), none());
        assert_eq!(page["has_more"], true);
        assert!(page["hint"].as_str().unwrap().contains("max_items"));
    }

    #[test]
    fn results_are_filtered_structured_and_cut() {
        let list = tool("things list");
        let page = json!({"items": [{"id": "a", "n": 1}, {"id": "b", "n": 2}],
                          "has_more": false, "next": null});
        let jq = Jq::compile("[.[] | .id]").unwrap();
        let full = Shape {
            structured: true,
            max_chars: 0,
        };
        let result = full.result(&list, page.clone(), Some(&jq));
        assert_eq!(
            result["structuredContent"],
            json!({"jq": ["a", "b"], "has_more": false, "next": null})
        );
        let text: Value =
            serde_json::from_str(result["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(text, result["structuredContent"]);
        let legacy = Shape {
            structured: false,
            max_chars: 0,
        };
        assert!(legacy
            .result(&list, page, None)
            .get("structuredContent")
            .is_none());

        let small = Shape {
            structured: true,
            max_chars: 40,
        };
        let many = json!({"items": [{"id": "a"}, {"id": "b"}, {"id": "c"}, {"id": "d"}],
                          "has_more": false, "next": null});
        let cut = &small.result(&list, many, None)["structuredContent"];
        assert!(cut["items"].as_array().unwrap().len() < 4);
        assert_eq!(cut["has_more"], true);
        assert!(cut["next"]["starting_after"].is_string());
        assert!(cut["hint"].as_str().unwrap().starts_with("Cut to"));

        let create = tool("things create");
        let big = json!({"id": "x", "note": "y".repeat(100)});
        let done = &small.result(&create, big.clone(), None)["structuredContent"]["result"];
        assert!(done.as_str().unwrap().starts_with("The request succeeded."));
        let failed = small.result(&tool("things list"), big, None);
        assert_eq!(failed["isError"], true);
        assert!(failed.get("structuredContent").is_none());
        let error: Value =
            serde_json::from_str(failed["content"][0]["text"].as_str().unwrap()).unwrap();
        assert_eq!(error["error"]["kind"], "output");
        assert_eq!(error["error"]["fields"], json!(["id", "note"]));
        assert!(error["error"].get("status").is_none());
    }

    #[test]
    fn toolsets_choose_tools_and_options_win_over_them() {
        let config = json!({
            "toolsets": {"reads": ["things_list", "things_pages"], "admin": ["things_delete"]},
            "default_toolsets": ["reads"],
            "operations": {"things_archive": {"hidden": true, "title": "Archive it",
                "annotations": {"destructiveHint": false}}},
        });
        let schema = schema();
        let tools: Vec<Tool> = schema
            .index(&[])
            .iter()
            .filter_map(|entry| Tool::new(&schema, entry, &config["operations"]))
            .collect();
        let archive = tools.iter().find(|t| t.name == "things_archive").unwrap();
        assert_eq!(archive.title, "Archive it");
        assert_eq!(archive.annotations["destructiveHint"], false);
        assert_eq!(archive.annotations["readOnlyHint"], false);
        let served = |args: &[&str]| {
            let matches = Command::new("mcp")
                .args(command(&APP, None).get_arguments().cloned())
                .try_get_matches_from(std::iter::once("mcp").chain(args.iter().copied()))
                .unwrap();
            let selection = Selection::new(&config, &matches).unwrap();
            let names: Vec<&str> = (tools.iter())
                .filter(|tool| selection.serves(tool))
                .map(|tool| tool.name.as_str())
                .collect();
            names
        };
        assert_eq!(
            served(&[]),
            ["things_list", "things_pages", "things_create"]
        );
        assert_eq!(
            served(&["--toolsets", "admin"]),
            ["things_create", "things_delete"]
        );
        assert_eq!(served(&["--toolsets", "all"]).len(), 5);
        assert_eq!(
            served(&["--toolsets", "all", "--read-only"]),
            ["things_list", "things_pages"]
        );
        assert_eq!(served(&["--tools", "*_archive"]), ["things_archive"]);
        assert_eq!(
            served(&["--exclude-tools", "things_pages"]),
            ["things_list", "things_create"]
        );
        let matches = Command::new("mcp")
            .args(command(&APP, None).get_arguments().cloned())
            .try_get_matches_from(["mcp", "--toolsets", "raeds"])
            .unwrap();
        let error = Selection::new(&config, &matches).err().unwrap();
        assert_eq!(
            error.message(),
            "--toolsets: no toolset `raeds`: did you mean reads? expected all or one of reads, admin"
        );
    }

    #[test]
    fn tools_take_the_names_of_perseid_toml_checked() {
        let named = |operations: Value| {
            let mcp = json!({"mcp": {"operations": operations,
                "toolsets": {"reads": ["things_list", "fetch_*"]}, "default_toolsets": []}});
            let schema = Schema::parse(&[&part().to_string(), &mcp.to_string()]).unwrap();
            let tools = tools(&schema).map_err(|error| error.message().to_owned())?;
            let config = schema.mcp().clone();
            let matches = Command::new("mcp")
                .args(command(&APP, None).get_arguments().cloned())
                .try_get_matches_from(["mcp", "--exclude-tools", "*_delete"])
                .unwrap();
            let selection = Selection::new(&config, &matches).unwrap();
            let served: Vec<String> = (tools.into_iter())
                .filter(|tool| selection.serves(tool))
                .map(|tool| tool.name)
                .collect();
            Ok::<_, String>(served)
        };
        let served = named(json!({"things_pages": {"name": "fetch_pages"},
            "things_archive": {"name": "archive-thing"}}));
        assert_eq!(
            served.unwrap(),
            ["things_create", "archive-thing"],
            "toolsets, --tools and --exclude-tools match the names served"
        );
        assert_eq!(
            named(json!({"things_pages": {"name": "things list"}})).unwrap_err(),
            "[context.cli_mcp.operations.things_pages] name = \"things list\": a tool name is 1 to \
             64 of A-Z, a-z, 0-9, _, . and -"
        );
        assert!(named(json!({"things_pages": {"name": "x".repeat(65)}})).is_err());
        assert!(named(json!({"things_pages": {"name": 1}})).is_err());
        assert_eq!(
            named(json!({"things_archive": {"name": "things_delete"}})).unwrap_err(),
            "two tools are named things_delete, of `things delete` and `things archive`: \
             [context.cli_mcp.operations.<tool>] name gives one another"
        );
        let swapped = json!({"things_archive": {"name": "things_delete"},
            "things_delete": {"name": "things_archive"}});
        assert!(
            named(swapped).is_ok(),
            "names are checked once all are given"
        );
    }

    #[test]
    fn globs_names_and_base64() {
        assert!(glob("things_*", "things_list"));
        assert!(glob("*_list", "things_list") && glob("th?ngs_list", "things_list"));
        assert!(!glob("things_*", "plans_list") && !glob("list", "things_list"));
        assert!(glob("a*b*c", "aXbYbc"));
        assert_eq!(tool_name("things list-all"), "things_list_all");
        assert_eq!(title("List things.", "things list"), "List things");
        assert_eq!(title("", "things list"), "Things list");
        assert_eq!(base64(b"%PDF"), "JVBERg==");
        assert_eq!(base64(b"ab"), "YWI=");
        assert_eq!(base64(b"abc"), "YWJj");
        assert_eq!(base64(b""), "");
    }
}
